   375	      } catch (final Exception ex) {
   376	        DecompilerContext.getLogger().writeMessage("Failed to close context unit " + unit.getName(), IFernflowerLogger.Severity.ERROR, ex);
   377	      }
   378	    }
   379	    this.units.clear();
   380	    this.unitsByClassName.clear();

