   133	  public void save(final Function<String, StructClass> loader) throws IOException {
   134	    if (!this.isOwn()) {
   135	      throw new IllegalStateException("Trying to save non-own unit?");
   136	    }
   137	
   138	    this.initEntries();
   139	    final IContextSource.IOutputSink sink = this.source.createOutputSink(this.resultSaver);
   140	    if (sink == null) {
   141	      throw new IllegalStateException("Context source " + this.source + " cannot be saved, but had a save requested.");
   142	    }
   143	
   144	    sink.begin();
   145	
   146	    final DecompilerContext rootContext = DecompilerContext.getCurrentContext();
   147	
   148	    Set<String> otherNames = otherEntries.stream().map(IContextSource.Entry::path).collect(Collectors.toSet());
   149	
   150	    // directory entries
   151	    for (String dirEntry : dirEntries) {
   152	      boolean write = true;
   153	      if (!rootContext.classProcessor.isWhitelisted(dirEntry)) {
   154	        // not allowed? check if an other entry starts with this path
   155	        write = otherNames.stream().anyMatch(s -> s.startsWith(dirEntry));
   156	      }
   157	
   158	      if (write) {
   159	        sink.acceptDirectory(dirEntry);
   160	      }
   161	    }
   162	
   163	    // non-class entries
   164	    for (String otherEntry : otherNames) {
   165	      sink.acceptOther(otherEntry);
   166	    }
   167	
   168	    //Whooo threads!
   169	    List<Future<?>> futures = new ArrayList<>();
   170	    int threads = Integer.parseInt((String) DecompilerContext.getProperty(IFernflowerPreferences.THREADS));
   171	    if (threads <= 0) {
   172	      threads = Runtime.getRuntime().availableProcessors();
   173	    }
   174	    ForkJoinPool pool = new ForkJoinPool(threads, namingScheme(), null, true);
   175	    final List<ClassContext> toDump = new ArrayList<>(classEntries.size());
   176	    Set<String> seen = new LinkedHashSet<>();
   177	
   178	    // collect classes
   179	    for (int i = 0; i < classEntries.size(); i++) {
   180	      StructClass cl = loader.apply(classEntries.get(i));
   181	      String entryName = decompiledData.getClassEntryName(cl, classEntries.get(i));
   182	      if (entryName != null) {
   183	        if (seen.add(cl.qualifiedName)) {
   184	          toDump.add(new ClassContext(cl, entryName));
   185	        } else {
   186	          DecompilerContext.getLogger().writeMessage("Skipping writing already existing class: " + cl.qualifiedName, IFernflowerLogger.Severity.ERROR);
   187	        }
   188	      }
   189	    }
   190	
   191	    // pre-process
   192	    for (final ClassContext classCtx : toDump) {
   193	      futures.add(pool.submit(() -> {
   194	        setContext(rootContext);
   195	        classCtx.ctx = DecompilerContext.getCurrentContext();
   196	        try {
   197	          decompiledData.processClass(classCtx.cl);
   198	        } catch (final Throwable thr) {
   199	          DecompilerContext.getLogger().writeMessage("Class " + classCtx.cl.qualifiedName + " couldn't be fully decompiled.", thr);
   200	          classCtx.onError(thr);
   201	        } finally {
   202	          DecompilerContext.setCurrentContext(null);
   203	        }
   204	      }));
   205	    }
   206	
   207	    waitForAll(futures);
   208	    futures.clear();
   209	
   210	    // emit
   211	    for (final ClassContext classCtx : toDump) {
   212	      if (classCtx.pendingError != null) {
   213	        TextBuffer buf = new TextBuffer();
   214	        ClassWriter.writeException(buf, classCtx.pendingError);
   215	        classCtx.classContent = buf.convertToStringAndAllowDataDiscard();
   216	        continue;
   217	      }
   218	
   219	      futures.add(pool.submit(() -> {
   220	        DecompilerContext.setCurrentContext(classCtx.ctx);
   221	        classCtx.classContent = decompiledData.getClassContent(classCtx.cl);
   222	        if (DecompilerContext.getOption(IFernflowerPreferences.BYTECODE_SOURCE_MAPPING)) {
   223	          classCtx.mapping = DecompilerContext.getBytecodeSourceMapper().getOriginalLinesMapping();
   224	        }
   225	      }));
   226	    }
   227	
   228	    waitForAll(futures);
   229	    futures.clear();
   230	    pool.shutdown();
   231	    THREAD_ID.set(0);
   232	
   233	    // write to file
   234	    for (final ClassContext cls : toDump) {
   235	      if (cls.classContent != null) {
   236	        sink.acceptClass(cls.cl.qualifiedName, cls.entryName, cls.classContent, cls.mapping);
   237	      }
   238	    }
   239	
   240	    sink.close();
   241	  }
