#!/usr/bin/env python3
import sys
from pathlib import Path

lines = sys.stdin.read().splitlines()
if not lines or lines[0] != '*** Begin Patch' or lines[-1] != '*** End Patch':
    raise SystemExit('invalid patch envelope')
i = 1
while i < len(lines) - 1:
    header = lines[i]
    if header.startswith('*** Add File: '):
        path = Path(header[14:])
        i += 1
        content = []
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            if not lines[i].startswith('+'):
                raise SystemExit(f'invalid add line: {lines[i]}')
            content.append(lines[i][1:])
            i += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(content) + '\n')
    elif header.startswith('*** Delete File: '):
        Path(header[17:]).unlink()
        i += 1
    elif header.startswith('*** Update File: '):
        path = Path(header[17:])
        source = path.read_text()
        i += 1
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            if not lines[i].startswith('@@'):
                raise SystemExit(f'expected hunk, got: {lines[i]}')
            i += 1
            old, new = [], []
            while i < len(lines) - 1 and not lines[i].startswith('@@') and not lines[i].startswith('*** '):
                line = lines[i]
                if line.startswith(' '):
                    old.append(line[1:]); new.append(line[1:])
                elif line.startswith('-'):
                    old.append(line[1:])
                elif line.startswith('+'):
                    new.append(line[1:])
                else:
                    raise SystemExit(f'invalid hunk line: {line}')
                i += 1
            old_text = '\n'.join(old)
            new_text = '\n'.join(new)
            if old_text not in source:
                raise SystemExit(f'hunk not found in {path}:\n{old_text}')
            if source.count(old_text) != 1:
                raise SystemExit(f'hunk ambiguous in {path}:\n{old_text}')
            source = source.replace(old_text, new_text, 1)
        path.write_text(source)
    else:
        raise SystemExit(f'unknown header: {header}')
